/* Client half of the Minecraft skin bundle.
 *
 * Generated by scripts/build_plugin.py from skin/skin.css + skin/tokens.mc.json
 * + skin/sprites/*.{png,svg} (all inlined as data URIs). Edit those sources and
 * rebuild; do not hand-edit this file.
 */

window.__ModuleLoader__.load({
  id: 'dsh-mc-valley',
  factory(require) {
    const CSS = __CSS__;
    const TOKENS = __TOKENS__;

    // Project the host's real context ring into a decorative XP-style bar.
    // Do not parse localized labels or write React-owned children. Unknown
    // geometry falls back to the native ring; every mutation is reversible.
    function installContextMeters() {
      if (typeof MutationObserver === 'undefined') return () => {};
      const selector = ':is(.A6Bq1a_trigger, .JObwrW_trigger)';
      const owned = new Map();
      function restore(button, previous) {
        if (previous.fill) button.style.setProperty('--mc-context-fill', previous.fill, previous.priority);
        else button.style.removeProperty('--mc-context-fill');
        if (previous.marker === null) button.removeAttribute('data-mc-context-meter');
        else button.setAttribute('data-mc-context-meter', previous.marker);
        owned.delete(button);
      }
      function update(button) {
        const fill = button.querySelector('circle:is(.A6Bq1a_fill, .JObwrW_fill)');
        const values = fill?.getAttribute('stroke-dasharray')?.trim().split(/[\s,]+/).map(Number);
        if (!values || values.length !== 2 || !values.every(Number.isFinite) || values[0] < 0 || values[1] <= 0) {
          if (owned.has(button)) restore(button, owned.get(button));
          return;
        }
        if (!owned.has(button)) owned.set(button, {
          fill: button.style.getPropertyValue('--mc-context-fill'),
          priority: button.style.getPropertyPriority('--mc-context-fill'),
          marker: button.getAttribute('data-mc-context-meter'),
        });
        button.style.setProperty('--mc-context-fill', `${Math.min(100, values[0] / values[1] * 100)}%`);
        button.setAttribute('data-mc-context-meter', '');
      }
      function scan(node) {
        if (node.nodeType !== 1) return;
        if (node.matches(selector)) update(node);
        node.querySelectorAll(selector).forEach(update);
      }
      document.querySelectorAll(selector).forEach(update);
      const observer = new MutationObserver(records => {
        const updates = new Set();
        for (const record of records) {
          if (record.type === 'attributes') {
            const button = record.target.closest(selector);
            if (button) updates.add(button);
          } else {
            const button = record.target.nodeType === 1 ? record.target.closest(selector) : null;
            if (button) updates.add(button);
            record.addedNodes.forEach(scan);
          }
        }
        updates.forEach(update);
        for (const [button, previous] of owned) if (!button.isConnected) restore(button, previous);
      });
      observer.observe(document.documentElement, {subtree: true, childList: true, attributes: true, attributeFilter: ['stroke-dasharray']});
      return () => {
        observer.disconnect();
        for (const [button, previous] of owned) restore(button, previous);
      };
    }

    // Opt-in UI click sound (D2). Off unless the user turns it on explicitly;
    // the engine is synthesized at runtime (no sampled or vanilla audio), one
    // short blip per accepted press, rate limited, and fully released on
    // dispose. There is no in-app settings row yet, so the only switch is the
    // documented window.__dshMinecraftSkin.sound API; the bundle never plays
    // anything on its own.
    function installSounds() {
      const Ctor = window.AudioContext || window.webkitAudioContext;
      if (typeof Ctor !== 'function') return () => {};
      const STORE = 'dsh-minecraft-skin:sound';
      const api = {enabled: false};
      try { api.enabled = window.localStorage.getItem(STORE) === 'on'; } catch (error) { /* storage may be blocked */ }
      let audio = null, lastAt = 0;
      const persist = on => {
        api.enabled = on;
        try { on ? window.localStorage.setItem(STORE, 'on') : window.localStorage.removeItem(STORE); } catch (error) { /* ignore */ }
      };
      api.enable = () => persist(true);
      api.disable = () => persist(false);
      const blip = () => {
        if (!audio) audio = new Ctor();
        if (audio.state === 'suspended') audio.resume().catch(() => {});
        const at = audio.currentTime;
        const osc = audio.createOscillator();
        const gain = audio.createGain();
        osc.type = 'square';
        osc.frequency.setValueAtTime(680, at);
        osc.frequency.exponentialRampToValueAtTime(420, at + 0.05);
        gain.gain.setValueAtTime(0.0001, at);
        gain.gain.exponentialRampToValueAtTime(0.05, at + 0.008);
        gain.gain.exponentialRampToValueAtTime(0.0001, at + 0.07);
        osc.connect(gain).connect(audio.destination);
        osc.start(at);
        osc.stop(at + 0.08);
      };
      const onPress = event => {
        if (!api.enabled) return;
        const target = event.target instanceof Element ? event.target.closest('button, [role="button"]') : null;
        if (!target || target.disabled || target.getAttribute('aria-disabled') === 'true') return;
        const now = typeof performance !== 'undefined' ? performance.now() : Date.now();
        if (now - lastAt < 90) return;
        lastAt = now;
        try { blip(); } catch (error) { /* audio must never break the click */ }
      };
      document.addEventListener('pointerdown', onPress, true);
      window.__dshMinecraftSkin = Object.assign(window.__dshMinecraftSkin || {}, {sound: api});
      return () => {
        document.removeEventListener('pointerdown', onPress, true);
        if (audio && typeof audio.close === 'function') audio.close().catch(() => {});
        audio = null;
        if (window.__dshMinecraftSkin && window.__dshMinecraftSkin.sound === api) delete window.__dshMinecraftSkin.sound;
      };
    }

    // Register the skin as a real third-party theme id (D5). The host folds a
    // registered theme's alias overrides into the snapshot when the preference
    // names it; registering is idempotent-safe because a duplicate id throws and
    // we keep the already registered one. The stored preference is never touched
    // here - the Appearance setting still belongs to the user.
    function registerSkinTheme(ctx) {
      const service = ctx.theme;
      if (!service || typeof service.register !== 'function') return () => {};
      try {
        return service.register({id: 'minecraft', colorScheme: 'light', tokens: TOKENS});
      } catch (error) {
        if (String(error && error.message).includes('already registered')) return () => {};
        console.warn('[dsh-minecraft-skin] theme registration rejected:', error);
        return () => {};
      }
    }

    return {
      inject: ['theme'],
      apply(ctx) {
        ctx.effect(() => registerSkinTheme(ctx));

        ctx.effect(installSounds);
        // Texture layer first: one plugin-owned stylesheet, removed on dispose.
        ctx.effect(() => {
          const tag = document.createElement('style');
          tag.dataset.pluginCss = 'dsh-mc-valley';
          tag.textContent = CSS;
          document.head.appendChild(tag);
          // DSH can mount client modules after this immediately-loaded plugin.
          // Keep their later styles from silently overriding equally-specific
          // skin rules, including modules loaded after the initial render.
          const observer = typeof MutationObserver === 'undefined' ? null : new MutationObserver(records => {
            const hostStyleAdded = records.some(record => Array.from(record.addedNodes).some(node =>
              node !== tag && node.nodeType === 1 && node.dataset?.pluginCss !== 'dsh-mc-valley' &&
              (node.tagName === 'STYLE' || (node.tagName === 'LINK' && node.rel === 'stylesheet'))));
            if (hostStyleAdded && tag.isConnected) document.head.appendChild(tag);
          });
          if (observer) observer.observe(document.head, {childList: true});
          return () => { observer?.disconnect(); tag.remove(); };
        });

        ctx.effect(installContextMeters);

        // Colour layer: rides on top of the user's light/dark choice without
        // touching the stored preference, and pops off on dispose. A rejected
        // override must not take the textures down with it.
        ctx.effect(() => {
          try {
            return ctx.theme.overrideTokens('dsh-mc-valley', TOKENS);
          } catch (error) {
            console.warn('[dsh-minecraft-skin] token layer rejected:', error);
            return () => {};
          }
        });
      },
    };
  },
});
